//! Native button events update live label lists while preserving App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn button_textarea_labels_actual_app_events_promoted_labels_paint_and_editor_identity(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-button-textarea-labels-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}label{position:absolute;left:20px;top:20px;width:160px;height:24px}#button{position:absolute;left:220px;top:20px;width:140px;height:32px}textarea{position:absolute;left:20px;top:100px;width:180px;height:60px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style><body><label id=label for=button>Initial</label><button id=button type=button>Change labels</button><textarea id=text>seed</textarea><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><div id=destination></div><script>var button=document.getElementById('button'),text=document.getElementById('text'),buttons=button.labels,texts=text.labels,round=0;text.id='A\ud800z';if(buttons.length!==1||texts.length)throw 'initial lists';button.onclick=function(e){if(!e.isTrusted)throw 'native pointer event';var label=document.getElementById('label');if(round===0){label.htmlFor='A\ud800z';label.textContent='Direct';}else if(round===1){var d=document.implementation.createHTMLDocument('source'),p=d.createElement('label');p.htmlFor='button';p.textContent='Imported';var copy=document.importNode(p,true);copy.id='label';label.parentNode.replaceChild(copy,label);label=copy;}else{var t=document.createElement('template');t.innerHTML='<label id=label for=seed>Promoted</label>';var p=t.content.firstChild;p.htmlFor='A\ud800z';var parent=label.parentNode;label.remove();parent.appendChild(t.content);label=p;}var chosen=round===1?button:text,list=round===1?buttons:texts,other=round===1?texts:buttons;if(button.labels!==buttons||text.labels!==texts||list.length!==1||list[0]!==label||other.length!==0||label.control!==chosen)throw 'current live native associations';document.title='Live labels '+round;round++;};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let button=node(&app,"button");let text=(0..app.document.nodes.len()).find(|&n|app.document.dom_attr(n,"id").is_some_and(|v|v.code_units().eq([65,0xd800,122]))).unwrap();let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;
 for round in 0..3{let rect=app.page.controls.iter().find(|r|r.node==button).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);let before=app.draw().pixels;app.pointer_down(x,y,false);app.pointer_up(x,y);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,format!("Live labels {round}"));let label=node(&app,"label");assert_eq!(crate::forms::label_targets(&app.document).get(&label),Some(if round==1{&button}else{&text}));assert_ne!(before,app.draw().pixels);if round!=1{let caption=if round==0{"Direct"}else{"Promoted"};let run=app.page.runs.iter().find(|r|r.text==caption).unwrap();let(x,y)=(run.x+2,app.content_top()+run.y+2);app.pointer_down(x,y,false);app.pointer_up(x,y);assert!(app.focus==Focus::Control(text));}let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.forms.controls[&text].value.text(),"seed");assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);}
}
